// === NORMALIZE INPUT & LOAD HISTORY ===
const telegramData = $input.first().json;
const username = telegramData.message?.from?.username || telegramData.message?.from?.first_name || 'User';
const message = telegramData.message?.text || '';
const chatId = telegramData.message?.chat?.id;

if (!message) {
  return { json: { error: 'No message text', chatId } };
}

// Load conversation history and memory from workflow static data
let conversationHistory = [];
let botMemory = '';

try {
  // Use $execution for accessing static data in n8n
  const staticData = $execution.getStaticData('global') || {};
  conversationHistory = staticData.conversationHistory || [];
  botMemory = staticData.botMemory || '';
} catch (e) {
  console.log('Initializing new conversation:', e);
}

// Add user message to history
conversationHistory.push({
  role: 'user',
  content: `${username}: ${message}`,
  timestamp: Date.now()
});

// Keep last 20 messages
if (conversationHistory.length > 20) {
  conversationHistory = conversationHistory.slice(-20);
}

// Save updated history back
try {
  const staticData = $execution.getStaticData('global');
  staticData.conversationHistory = conversationHistory;
  staticData.botMemory = botMemory;
} catch (e) {
  console.log('Could not save conversation history:', e);
}

console.log('=== NORMALIZE INPUT ===');
console.log('User Message:', message);
console.log('Chat ID:', chatId);
console.log('Username:', username);

return {
  json: {
    username,
    message,
    chatId,
    conversationHistory,
    botMemory,
    timestamp: Date.now(),
    source: 'normalize'
  }
};

// === MERGE STATUS DATA ===
const inputData = $('Normalize Input').first().json;
const statusResponse = $input.first().json;

console.log('=== MERGE STATUS ===');
console.log('Input data keys:', Object.keys(inputData));
console.log('Status response full:', JSON.stringify(statusResponse, null, 2));
console.log('Status response type:', typeof statusResponse);

// Process bot status
let botStatus = {};
if (statusResponse && !statusResponse.error) {
  botStatus = statusResponse;
  console.log('Bot Status Retrieved:', botStatus);
} else {
  console.log('Bot Status Error - using defaults');
  botStatus = { error: 'Status unavailable', health: 20, food: 20, position: { x: 0, y: 64, z: 0 } };
}

// Merge input data with bot status
return {
  json: {
    ...inputData,
    botStatus,
    source: 'status'
  }
};

// === MERGE INVENTORY DATA ===
const inputData = $('Merge Status Data').first().json;
const inventoryHttpResponse = $input.first().json;

console.log('=== MERGE INVENTORY ===');
console.log('Input data keys:', Object.keys(inputData));
console.log('Full HTTP Response:', JSON.stringify(inventoryHttpResponse, null, 2));

// Get the inventory data from the HTTP response
let botInventory = [];

// Direct access to inventory field since you confirmed it exists
if (inventoryHttpResponse && inventoryHttpResponse.inventory) {
  console.log('Inventory field found, type:', typeof inventoryHttpResponse.inventory);
  console.log('Inventory value:', inventoryHttpResponse.inventory);

  if (Array.isArray(inventoryHttpResponse.inventory)) {
    botInventory = inventoryHttpResponse.inventory;
    console.log('SUCCESS: Inventory is array with', botInventory.length, 'items');
  } else if (typeof inventoryHttpResponse.inventory === 'string') {
    console.log('Inventory is string:', inventoryHttpResponse.inventory);
    // Keep as empty array for string format
    botInventory = [];
  } else {
    console.log('Inventory unexpected type:', typeof inventoryHttpResponse.inventory);
    botInventory = [];
  }
} else {
  console.log('No inventory field or empty response');
  console.log('Available fields:', inventoryHttpResponse ? Object.keys(inventoryHttpResponse) : 'none');
  botInventory = [];
}

console.log('FINAL: botInventory length =', botInventory.length);
console.log('FINAL: botInventory =', botInventory);

// Merge input data with bot inventory
const result = {
  ...inputData,
  botInventory: botInventory,
  source: 'inventory'
};

console.log('RESULT: Final merged data keys:', Object.keys(result));
console.log('RESULT: botInventory in result:', result.botInventory);

return { json: result };

// === BUILD AI PROMPT WITH FULL CAPABILITY AWARENESS ===
const inputData = $input.first().json;

console.log('=== BUILD AI PROMPT ===');
console.log('Input data keys:', Object.keys(inputData));

// Extract all data from the sequential flow
const username = inputData.username || 'User';
const message = inputData.message || '';
const chatId = inputData.chatId;
const conversationHistory = inputData.conversationHistory || [];
const botMemory = inputData.botMemory || '';
const botStatus = inputData.botStatus || {};
const botInventory = inputData.botInventory || [];

console.log('User message:', message);
console.log('Bot status available:', !!botStatus);
console.log('Bot inventory available:', !!botInventory);

// Process bot status
let statusText = 'Status unavailable';
if (botStatus && !botStatus.error) {
  if (botStatus.position) {
    statusText = `Position: x:${botStatus.position.x?.toFixed(1)}, y:${botStatus.position.y?.toFixed(1)}, z:${botStatus.position.z?.toFixed(1)} | Health: ${botStatus.health}/20 | Action: ${botStatus.current_action || 'Idle'}`;
  } else if (botStatus.x !== undefined) {
    statusText = `Position: x:${botStatus.x?.toFixed(1)}, y:${botStatus.y?.toFixed(1)}, z:${botStatus.z?.toFixed(1)} | Health: ${botStatus.health || 20}/20 | Action: ${botStatus.current_action || 'Idle'}`;
  }
} else {
  statusText = 'Position: x:0, y:64, z:0 | Health: 20/20 | Action: Idle';
}

// Process inventory
let inventoryText = 'Inventory unavailable';
if (Array.isArray(botInventory) && botInventory.length > 0) {
  inventoryText = botInventory.map(item => `${item.name || item.type}(${item.count || item.quantity || 1})`).join(', ');
} else {
  inventoryText = 'Empty';
}

console.log('Final status:', statusText);
console.log('Final inventory: SKIPPED (creative mode)');

// Build comprehensive system prompt based on actual code capabilities
const systemPrompt = `You are a helpful Minecraft assistant. You can see, move, mine, build, craft, and interact with the world by using commands. You also have access to vision. Use vision when you're unsure what's in front of you, looking for resources, verifying something built, or navigating new areas. Your goal is to assist the user efficiently and accurately.

Speak concisely and avoid unnecessary filler. Do not act playful or in-character. Do not apologize unless something is truly wrong. Focus on being useful and responsive. When asked about your limitations, be honest and factual.

IMPORTANT: You must respond with a structured JSON output that contains an intent and parameters. ALWAYS try to map user requests to specific intents instead of using "chat". Only use "chat" if the user is truly just having a conversation. Use these exact intents based on what the user wants:

MOVEMENT INTENTS:
- "move" - Move to coordinates or direction (params: x, y, z OR direction)
- "goToPlayer" - Go to a specific player (params: player, closeness)
- "followPlayer" - Follow a player (params: player, distance)
- "moveAway" - Move away from threats (params: distance)
- "searchForBlock" - Find specific blocks (params: block, range)
- "searchForEntity" - Find entities/players (params: entity, range)

BLOCK OPERATION INTENTS:
- "collectBlocks" - Mine/collect blocks (params: block, quantity)
- "placeBlocks" - Place blocks at location (params: material, x, y, z, face)
- "digDown" - Mine downward (params: depth)
- "activate" - Use blocks/buttons/levers (params: x, y, z)

ITEM MANAGEMENT INTENTS:
- "equip" - Equip items/armor (params: item)
- "discard" - Drop unwanted items (params: item, quantity)
- "consume" - Eat food/drink potions (params: item, quantity)
- "givePlayer" - Transfer items to players (params: player, item, quantity)

CHEST OPERATIONS INTENTS:
- "putInChest" - Store items in chest (params: item, quantity, x, y, z)
- "takeFromChest" - Retrieve items from chest (params: item, quantity, x, y, z)
- "viewChest" - Check chest contents (params: x, y, z)

CRAFTING INTENTS:
- "craft" - Craft recipes (params: item, quantity)
- "smelt" - Smelt items in furnace (params: item, quantity)
- "clearFurnace" - Clean furnaces

COMBAT INTENTS:
- "attackPlayer" - Engage in combat (params: player)
- "defendSelf" - Defensive actions (params: range)

MEMORY & NAVIGATION INTENTS:
- "rememberHere" - Save current location (params: name)
- "goToRememberedPlace" - Return to saved places (params: name)
- "savedPlaces" - List saved locations

INFORMATION INTENTS:
- "nearbyBlocks" - Scan environment
- "craftable" - Check craftable items  
- "entities" - List nearby entities
- "modes" - Check bot modes
- "getCraftingPlan" - Calculate crafting requirements (params: item, quantity)
- "stats" - Get bot status
- "inventory" - Check inventory

MODE MANAGEMENT INTENTS:
- "setMode" - Toggle bot behaviors (params: mode, enabled)
- "stay" - Wait/pause actions (params: seconds)
- "goToBed" - Sleep functionality

UTILITY INTENTS:
- "useDoor" - Operate doors (params: x, y, z optional)
- "newAction" - Custom AI actions (params: prompt)
- "lookAtPlayer" - Vision system (params: player, direction)
- "lookAtPosition" - Look at coordinates (params: x, y, z)

COMMUNICATION INTENTS:
- "startConversation" - Begin bot conversations (params: player, message)
- "endConversation" - End conversations (params: player)

CONTROL INTENTS:
- "restart" - Restart the agent
- "clearChat" - Clear chat history
- "endGoal" - Stop current goals
- "stop" - Force stop all actions
- "chat" - Simple conversation response (params: response)

Current Status: ${statusText}
Current Inventory: Empty (Creative Mode)  
Summarized Memory: ${botMemory}

User said: "${message}"

You must respond with valid JSON in this exact format:
{
  "intent": "intentName",
  "params": {
    "paramName": "value"
  },
  "response": "Brief response message"
}

CRITICAL: Only use chat intent for casual conversation. For ANY action request (move, collect, craft, go, check, etc), use the appropriate action intent from the list above. Always use specific parameter names that match the API handlers.`;

return {
  json: {
    systemPrompt,
    userMessage: message,
    username,
    message,
    chatId,
    conversationHistory,
    botMemory,
    botStatus: statusText,
    botInventory: inventoryText
  }
};

// === PARSE & VALIDATE AI RESPONSE ===
const aiResponse = $input.first().json.message?.content || $input.first().json.text || '';
const promptData = $('Build AI Prompt').first().json;

console.log('AI Response:', aiResponse);
console.log('User message:', promptData.message);

let parsedIntent = null;

try {
  // Extract JSON from AI response (handle markdown code blocks)
  let jsonStr = aiResponse.trim();

  // Remove markdown code blocks if present
  if (jsonStr.includes('```json')) {
    jsonStr = jsonStr.split('```json')[1].split('```')[0].trim();
  } else if (jsonStr.includes('```')) {
    jsonStr = jsonStr.split('```')[1].split('```')[0].trim();
  }

  // Try to find JSON object in the response
  const jsonMatch = jsonStr.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    jsonStr = jsonMatch[0];
  }

  parsedIntent = JSON.parse(jsonStr);

  // Validate required fields
  if (!parsedIntent.intent || !parsedIntent.response) {
    throw new Error('Missing required fields: intent or response');
  }

  // Ensure params exists
  if (!parsedIntent.params) {
    parsedIntent.params = {};
  }

  console.log('Successfully parsed intent:', parsedIntent.intent);
  console.log('Successfully parsed params:', JSON.stringify(parsedIntent.params));

} catch (error) {
  console.error('Failed to parse AI response:', error.message);
  console.error('Raw AI response:', aiResponse);

  // ENHANCED FALLBACK: Pattern matching based on user message
  const message = promptData.message.toLowerCase();

  // Inventory patterns
  if (message.match(/(inventory|what.*have|what.*carrying|items|stuff)/)) {
    parsedIntent = {
      intent: 'inventory',
      params: {},
      response: 'Let me check my inventory...'
    };
  }
  // Status patterns
  else if (message.match(/(status|health|how.*you|where.*you|position)/)) {
    parsedIntent = {
      intent: 'stats',
      params: {},
      response: 'Checking my status...'
    };
  }
  // Movement patterns with direction
  else if (message.match(/(move|go|walk|run|travel)\s+(left|right|forward|back|north|south|east|west)/)) {
    const directionMatch = message.match(/(left|right|forward|back|north|south|east|west)/);
    const direction = directionMatch ? directionMatch[1] : 'forward';
    console.log('FALLBACK: Matched movement pattern, direction:', direction);
    parsedIntent = {
      intent: 'move',
      params: { direction: direction },
      response: `Moving ${direction}!`
    };
  }
  // Coordinate movement
  else if (message.match(/(move|go|travel).*(\d+).*(\d+).*(\d+)/)) {
    const coords = message.match(/(\d+)\s+(\d+)\s+(\d+)/);
    if (coords) {
      parsedIntent = {
        intent: 'move',
        params: { x: parseInt(coords[1]), y: parseInt(coords[2]), z: parseInt(coords[3]) },
        response: `Moving to coordinates ${coords[1]}, ${coords[2]}, ${coords[3]}!`
      };
    }
  }
  // Collection patterns
  else if (message.match(/(collect|get|mine|gather|pick)/)) {
    const blockMatch = message.match(/(collect|get|mine|gather|pick)\s+(?:(\d+)\s+)?(\w+)/);
    const quantity = blockMatch && blockMatch[2] ? parseInt(blockMatch[2]) : 10;
    const block = blockMatch && blockMatch[3] ? blockMatch[3] : 'dirt';
    parsedIntent = {
      intent: 'collectBlocks',
      params: { block: block, quantity: quantity },
      response: `Collecting ${quantity} ${block}!`
    };
  }
  // Place patterns
  else if (message.match(/(place|put|build)/)) {
    const placeMatch = message.match(/(place|put|build)\s+(\w+)/);
    const material = placeMatch && placeMatch[2] ? placeMatch[2] : 'dirt';
    parsedIntent = {
      intent: 'placeBlocks',
      params: { material: material },
      response: `Placing ${material}!`
    };
  }
  // Craft patterns
  else if (message.match(/(craft|make)/)) {
    const craftMatch = message.match(/(craft|make)\s+(?:(\d+)\s+)?(\w+)/);
    const quantity = craftMatch && craftMatch[2] ? parseInt(craftMatch[2]) : 1;
    const item = craftMatch && craftMatch[3] ? craftMatch[3] : 'stick';
    parsedIntent = {
      intent: 'craft',
      params: { item: item, quantity: quantity },
      response: `Crafting ${quantity} ${item}!`
    };
  }
  // Follow patterns
  else if (message.match(/(follow|come)/)) {
    const followMatch = message.match(/(follow|come)\s+(\w+)/);
    const player = followMatch && followMatch[2] ? followMatch[2] : 'player';
    parsedIntent = {
      intent: 'followPlayer',
      params: { player: player, distance: 3 },
      response: `Following ${player}!`
    };
  }
  // Stop patterns
  else if (message.match(/(stop|halt|cease|end)/)) {
    parsedIntent = {
      intent: 'stop',
      params: {},
      response: 'Stopping my current action!'
    };
  }
  // Default to chat
  else {
    parsedIntent = {
      intent: 'chat',
      params: {},
      response: aiResponse || "I didn't quite understand that. Can you be more specific?"
    };
  }

  console.log('Used fallback parsing, intent:', parsedIntent.intent);
}

// Basic parameter validation
const intent = parsedIntent.intent;
const params = parsedIntent.params;
let validationError = null;

switch (intent) {
  case 'move':
    console.log('VALIDATION: Move intent with params:', JSON.stringify(params));
    // Allow either coordinates OR direction
    if (!params.direction && (params.x === undefined || params.y === undefined || params.z === undefined)) {
      console.log('VALIDATION: Move validation failed - no direction and incomplete coordinates');
      validationError = 'Missing coordinates or direction for move command';
    } else {
      console.log('VALIDATION: Move validation passed');
    }
    break;
  case 'collectBlocks':
    if (!params.block) {
      params.block = 'dirt'; // Default block
      params.quantity = params.quantity || 10;
    }
    break;
  case 'placeBlocks':
    if (!params.material) {
      params.material = 'dirt'; // Default material
    }
    break;
  case 'goToPlayer':
    if (!params.player) {
      validationError = 'Missing player name for goToPlayer command';
    }
    break;
  case 'followPlayer':
    if (!params.player) {
      validationError = 'Missing player name for followPlayer command';
    }
    break;
}

if (validationError) {
  console.error('Validation error:', validationError);
  parsedIntent.intent = 'chat';
  parsedIntent.response = `I need more information: ${validationError}`;
}

console.log('Final intent:', parsedIntent.intent, 'params:', parsedIntent.params);
console.log('Will this go to clarification? Intent is chat:', (parsedIntent.intent === 'chat'));

return {
  json: {
    ...parsedIntent,
    chatId: promptData.chatId,
    username: promptData.username,
    originalMessage: promptData.message,
    conversationHistory: promptData.conversationHistory,
    botMemory: promptData.botMemory,
    rawAiResponse: aiResponse
  }
};

// === DEBUG BEFORE CHECK IF CHAT ===
const data = $input.first().json;

console.log('=== PRE-CHAT-CHECK DEBUG ===');
console.log('Input intent value:', data.intent);
console.log('Input intent type:', typeof data.intent);
console.log('Intent === "chat":', (data.intent === 'chat'));
console.log('Intent !== "chat":', (data.intent !== 'chat'));
console.log('Available data keys:', Object.keys(data));

// Pass through unchanged
return { json: data };

// === ROUTE CHAT ONLY ===
const data = $input.first().json;

console.log('=== CHAT ROUTER ===');
console.log('Intent:', data.intent);
console.log('Is chat?', (data.intent === 'chat'));

// Fix chat response formatting BEFORE routing
if (data.intent === 'chat' && data.params && data.params.response && !data.response) {
  console.log('🔧 FIXING: Moving chat response from params.response to response field');
  console.log('🔧 Original params.response:', data.params.response);
  data.response = data.params.response;
  delete data.params.response;
  console.log('🔧 Fixed response field:', data.response);
}

if (data.intent === 'chat') {
  console.log('🗨️ ROUTING TO: Chat Reply');
  return { json: data };
} else {
  console.log('⚡ ROUTING TO: Command Execution - stopping chat path');
  return null;
}

// === ROUTE COMMANDS ONLY ===
const data = $input.first().json;

console.log('=== COMMAND ROUTER ===');
console.log('Intent:', data.intent);
console.log('Is command?', (data.intent !== 'chat'));

if (data.intent !== 'chat') {
  console.log('⚡ ROUTING TO: Command Execution');
  // Only return data if it's a command, otherwise return nothing
  return { json: data };
} else {
  console.log('🗨️ ROUTING TO: Chat Reply - stopping command path');
  // Return empty for command path when it's chat
  return null;
}

// === SAVE CONVERSATION & SEND REPLY ===
const data = $input.first().json;

console.log('Save & Reply - Input data:', JSON.stringify(data, null, 2));

// Ensure we have a valid chatId
if (!data.chatId) {
  console.error('Missing chatId in Save & Reply node');
  console.log('Available data keys:', Object.keys(data));
} else {
  console.log('ChatId found:', data.chatId, 'Type:', typeof data.chatId);
}

// Save bot response to conversation history
const conversationHistory = data.conversationHistory || [];
conversationHistory.push({
  role: 'assistant',
  content: data.response,
  timestamp: Date.now()
});

// Keep last 20 messages
if (conversationHistory.length > 20) {
  conversationHistory.splice(0, conversationHistory.length - 20);
}

// Save to workflow static data
try {
  const workflowData = $workflow.getStaticData();
  workflowData.conversationHistory = conversationHistory;
  workflowData.botMemory = data.botMemory || '';
} catch (e) {
  console.error('Failed to save conversation history:', e);
}

console.log('Save & Reply - Final output chatId:', data.chatId, 'response:', data.response);

return {
  json: {
    chatId: data.chatId,
    text: data.response,
    conversationHistory
  }
};

// === FORMAT RESULT FOR USER ===
const intentData = $('Route by Intent').first().json;
const executionResult = $input.first().json;

let finalMessage = intentData.response;

// If execution failed, append error
if (executionResult.error) {
  finalMessage += `\n\n⚠️ Error: ${executionResult.error}`;
} else if (executionResult.message && executionResult.message !== intentData.response) {
  finalMessage += `\n\n✅ ${executionResult.message}`;
}

// For status/inventory, include the data
if (intentData.intent === 'stats' && executionResult.position) {
  finalMessage = `Position: x:${executionResult.position.x?.toFixed(1)}, y:${executionResult.position.y?.toFixed(1)}, z:${executionResult.position.z?.toFixed(1)}\nHealth: ${executionResult.health}/20\nHunger: ${executionResult.hunger}/20\nAction: ${executionResult.current_action || 'Idle'}`;
} else if (intentData.intent === 'inventory' && executionResult.inventory) {
  const items = Array.isArray(executionResult.inventory) ? 
    executionResult.inventory.map(item => `${item.name}(${item.count})`).join(', ') : 
    'Empty';
  finalMessage = `Inventory: ${items}`;
} else if (intentData.intent === 'nearbyBlocks' && executionResult.nearby_blocks) {
  finalMessage = `Nearby blocks: ${executionResult.nearby_blocks}`;
} else if (intentData.intent === 'entities' && executionResult.nearby_entities) {
  finalMessage = `Nearby entities: ${executionResult.nearby_entities}`;
} else if (intentData.intent === 'craftable' && executionResult.craftable_items) {
  finalMessage = `Craftable items: ${executionResult.craftable_items}`;
} else if (intentData.intent === 'modes' && executionResult.modes) {
  finalMessage = `Bot modes: ${executionResult.modes}`;
} else if (intentData.intent === 'savedPlaces' && executionResult.saved_places) {
  finalMessage = `Saved places: ${executionResult.saved_places}`;
} else if (intentData.intent === 'getCraftingPlan' && executionResult.crafting_plan) {
  finalMessage = `Crafting plan: ${executionResult.crafting_plan}`;
} else if (intentData.intent === 'lookAtPlayer' && executionResult.vision_result) {
  finalMessage = `Vision: ${executionResult.vision_result}`;
} else if (intentData.intent === 'lookAtPosition' && executionResult.vision_result) {
  finalMessage = `Vision: ${executionResult.vision_result}`;
}

// Save bot response to conversation history
const conversationHistory = intentData.conversationHistory || [];
conversationHistory.push({
  role: 'assistant',
  content: finalMessage,
  timestamp: Date.now()
});

// Keep last 20 messages
if (conversationHistory.length > 20) {
  conversationHistory.splice(0, conversationHistory.length - 20);
}

// Save to workflow static data
try {
  const workflowData = $workflow.getStaticData();
  workflowData.conversationHistory = conversationHistory;
  workflowData.botMemory = intentData.botMemory || '';
} catch (e) {
  console.error('Failed to save conversation history:', e);
}

return {
  json: {
    chatId: intentData.chatId,
    text: finalMessage,
    conversationHistory,
    executionResult
  }
};
